time_order = ['Off-Peak', 'Mid-Peak', 'Peak']
wait_time_pivot = wait_time_pivot.reindex(columns=[t for t in time_order if t in wait_time_pivot.columns])
sns.heatmap(wait_time_pivot, annot=True, cmap='YlOrRd', fmt='.1f', ax=ax1)
ax1.set_title('Average Waiting Time (min) by Location and Time Slot')
ax1.set_ylabel('Location Type')
ax1.set_xlabel('Time Slot')
chart1_b64 = get_base64_image(fig1)

# Chart 2: Station Utilization & Demand Analysis
fig2, ax2 = plt.subplots(figsize=(10, 6))
demand_by_loc = df.groupby('location_type')['charging_demand'].mean().reset_index()
sns.barplot(data=demand_by_loc, x='location_type', y='charging_demand', palette='viridis', ax=ax2)
ax2.set_title('Average Charging Demand by Location Type')
ax2.set_ylabel('Avg Charging Demand')
ax2.set_xlabel('Location Type')
chart2_b64 = get_base64_image(fig2)

# Chart 3: Energy Consumption & Grid Load Patterns
