# Sort by custom order
load_by_time['time_slot'] = pd.Categorical(load_by_time['time_slot'], categories=time_order, ordered=True)
load_by_time = load_by_time.sort_values('time_slot')
sns.lineplot(data=load_by_time, x='time_slot', y='station_load', marker='o', ax=ax3, linewidth=2, color='coral')
ax3.set_title('Mean Station Load by Time Slot')
ax3.set_ylabel('Mean Station Load (kW)')
ax3.set_xlabel('Time Slot')
chart3_b64 = get_base64_image(fig3)

# Chart 4: Renewable Energy Ratio by Weather
fig4, ax4 = plt.subplots(figsize=(10, 6))
renew_by_weather = df.groupby('weather_condition')['renewable_energy_ratio'].mean().reset_index().sort_values('renewable_energy_ratio', ascending=False)
sns.barplot(data=renew_by_weather, x='weather_condition', y='renewable_energy_ratio', palette='Greens_r', ax=ax4)
ax4.set_title('Renewable Energy Ratio by Weather Condition')
ax4.set_ylabel('Renewable Energy Ratio')
ax4.set_xlabel('Weather Condition')
plt.xticks(rotation=45)
chart4_b64 = get_base64_image(fig4)

# Chart 5: Vehicle Charging Behavior
fig5, ax5 = plt.subplots(figsize=(10, 6))
energy_by_vehicle = df.groupby('vehicle_type')['energy_consumed_kWh'].mean().reset_index().sort_values('energy_consumed_kWh', ascending=False)
sns.barplot(data=energy_by_vehicle, x='vehicle_type', y='energy_consumed_kWh', palette='Blues_r', ax=ax5)
